mapper.select:
SELECT COALESCE(SUM(quantity), 0)
FROM orders
WHERE user_id = #{userId}
AND ticket_id = #{ticketId}
AND order_status = 'PURCHASED'

mapper.update:
UPDATE orders
SET order_status = 'CANCELED',
canceled_at = NOW()
WHERE order_id = #{orderId}
AND user_id = #{userId}
AND order_status = 'PURCHASED'
